            res[i][j] %= mod
    return res

def mat_pow(mat, n, mod):
    size = len(mat)
    res = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    while n > 0:
        if n & 1:
            res = mat_mul(res, mat, mod)
        mat = mat_mul(mat, mat, mod)
        n >>= 1
    return res

