    def distributeCandies(self, n: int, limit: int) -> int:
        # Define a lambda function for combinations
        comb = lambda x: x * (x - 1) // 2

        # Check if n is greater than 3 times limit
        if n > 3 * limit:
            return 0

        ans = comb(n + 2)

        if n > limit:
            ans -= 3 * comb(n - limit + 1)

        if n - 2 >= 2 * limit:
            ans += 3 * comb(n - 2 * limit)

