class Solution:
    def maxFreeTime(self, eventTime: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        if n == 0:
            return eventTime

        # Compute original free intervals' sizes
        pre_size = startTime[0] - 0
        mid_sizes = [startTime[i+1] - endTime[i] for i in range(n-1)]
        post_size = eventTime - endTime[-1]
        original_sizes = [pre_size] + mid_sizes + [post_size]

        # Precompute prefix and suffix max arrays
        m = len(original_sizes)
        prefix_max = [0] * m
        prefix_max[0] = original_sizes[0]
        for j in range(1, m):
            prefix_max[j] = max(prefix_max[j-1], original_sizes[j])

        suffix_max = [0] * m
        suffix_max[-1] = original_sizes[-1]
        for j in range(m-2, -1, -1):
            suffix_max[j] = max(suffix_max[j+1], original_sizes[j])

        original_max = max(original_sizes)
        max_candidate = 0

        for i in range(n):
            # Calculate S_size (merged interval after removing meeting i)
            if i > 0:
                prev_end = endTime[i-1]
            else:
                prev_end = 0
            if i < n-1:
                next_start = startTime[i+1]
            else:
                next_start = eventTime
            S_size = next_start - prev_end
            d = endTime[i] - startTime[i]

            # Determine max_remaining (max of original_sizes excluding i and i+1)
            if i == 0:
                if m >= 2:
                    max_remaining = suffix_max[2] if 2 < m else 0
                else:
                    max_remaining = 0
            elif i == n-1:
                max_remaining = prefix_max[n-2] if (n-2) >= 0 else 0
            else:
                left_part = prefix_max[i-1] if (i-1) >= 0 else 0
                right_part = suffix_max[i+2] if (i+2) < m else 0
                max_remaining = max(left_part, right_part)

            # Calculate options for inserting into S or max_remaining
            option1 = 0
            if S_size >= d:
                option1 = max(S_size - d, max_remaining)

            option2 = 0
            if max_remaining >= d:
                option2 = max(max_remaining - d, S_size)

            current_candidate = max(option1, option2)
            if current_candidate > max_candidate:
                max_candidate = current_candidate

        return max(original_max, max_candidate)

