        while x<self.n:
            self.arr[x]+=v
            x+=x&-x
    def query(self,x):
        ans=0
        while x:
            ans+=self.arr[x]
            x&=x-1
        return ans
    def prod(self,l,r):
        return self.query(r)-self.query(l-1)
