def cartesian(a):
    ch=A2(n+1,2)
    stk=[0]
    for i in range(1,n+1):
        while stk and a[stk[-1]]>a[i]:
            stk.pop()
        ch[i][0]=ch[stk[-1]][1]
        ch[stk[-1]][1]=i
        stk.append(i)
    rt=stk[1]
    return rt,ch
